import socket, struct, random, concurrent.futures

def dns_raw(name, qtype=1):
    tid = random.randint(0,65535)
    header = struct.pack(">HHHHHH", tid, 0x0100, 1, 0, 0, 0)
    q = b""
    for label in name.rstrip(".").split("."):
        if not label: continue
        q += bytes([len(label)]) + label.encode()
    try:
        q += b"\x00" + struct.pack(">HH", qtype, 1)
    except Exception as e:
        return None
    pkt = header + q
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM); s.settimeout(2)
    try:
        s.sendto(pkt, ("127.0.0.11", 53))
        data, _ = s.recvfrom(4096)
        return data
    except Exception:
        return None
    finally:
        s.close()

def parse(data):
    if not data or len(data)<12: return []
    ancount = struct.unpack(">H", data[6:8])[0]
    off=12
    def skip(pos):
        while pos < len(data) and data[pos]:
            if data[pos] & 0xC0 == 0xC0:
                return pos+2
            pos += data[pos]+1
        return pos+1
    off = skip(off)+4
    out=[]
    for i in range(ancount):
        ne = skip(off)
        try:
            rtype, rclass, ttl, rdlen = struct.unpack(">HHIH", data[ne:ne+10])
        except Exception:
            break
        rdata = data[ne+10:ne+10+rdlen]
        if rtype==1 and rdlen==4:
            out.append(".".join(str(b) for b in rdata))
        off = ne+10+rdlen
    return out

# PTR sweep for all IPs in 172.20.0.0/24 to enumerate container names
def ptr(i):
    data = dns_raw(f"{i}.0.20.172.in-addr.arpa", 12)
    if data:
        # extract the PTR name text roughly: find \xc\x0c or the domain part
        return i, data.hex()
    return i, None

with concurrent.futures.ThreadPoolExecutor(max_workers=64) as ex:
    for i,hexd in ex.map(ptr, range(1,60)):
        if hexd:
            print(i, hexd)
EOF"}

